<script setup lang="ts">
import { t } from '@/i18n';
import { computed, onMounted, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import { api } from '@/app/runtime';
import { useSessionStore } from '@/stores/session';
import { useSettingsStore } from '@/stores/settings';
import { useAsync } from '@/composables/useAsync';
import type { JsonObject } from '@/api/types';
const router = useRouter(); const session = useSessionStore(); const settings = useSettingsStore(); const query = useAsync<JsonObject>(); const security = useAsync<JsonObject>(); const securityEnabled = computed(() => security.data.value?.enabled === true); const edit = ref(false); const error = ref(''); const saving = ref(false); const form = reactive({ nickname: '', bio: '', region: '', socialMedia: '', showRegistrations: false });
onMounted(async () => { const profile = await query.run(() => api.profile.get()); if (profile) Object.assign(form, profile); await security.run(() => api.security.get()); });
async function save() { error.value = ''; saving.value = true; try { const result = await api.profile.save({ ...form }); if (result.ok === false) throw new Error(String(result.error || t('s_1q9u8le'))); session.applyUser({ ...session.user, ...form }); edit.value = false; } catch (reason) { error.value = reason instanceof Error ? reason.message : String(reason); } finally { saving.value = false; } }
async function logout() { await api.auth.logout(); session.clear(); await router.replace('/login'); }
</script>
<template><section class="page"><header class="topbar"><h1>{{ t('s_1x6gkn2') }}</h1><button class="text-action" @click="logout">{{ t('s_12hokt7') }}</button></header><div v-if="query.loading" class="state">{{ t('s_zw67ah') }}</div><div v-else-if="query.error" class="state error">{{ query.error.value?.message }}<button @click="query.run(() => api.profile.get())">{{ t('s_lswd2v') }}</button></div><template v-else><article class="card"><h2>{{ session.user.nickname || session.user.username }}</h2><p class="muted">{{ session.user.email }}</p><p class="muted">{{ session.user.roleLabel || session.user.role }} · {{ session.user.status }}</p></article><form v-if="edit" class="card form" @submit.prevent="save"><label>{{ t('s_1c2rfxc') }}<input v-model="form.nickname" maxlength="20"></label><label>{{ t('s_xr45ks') }}<textarea v-model="form.bio" maxlength="200"></textarea></label><label>{{ t('s_11ftk7j') }}<input v-model="form.region"></label><label>{{ t('s_gy710i') }}<input v-model="form.socialMedia"></label><label><input v-model="form.showRegistrations" type="checkbox">{{ t('s_1rrhfis') }}</label><p v-if="error" class="error">{{ error }}</p><button class="cta" :disabled="saving">{{ t('s_1c3mapc') }}</button></form><button v-else class="cta ghost" :disabled="session.user.can?.profile === false" @click="edit = true">{{ t('s_1sq2bvr') }}</button><article class="card"><h2>{{ t('s_jtetbl') }}</h2><label>{{ t('s_10317x5') }}<select :value="settings.mode" @change="settings.setMode(($event.target as HTMLSelectElement).value as 'auto' | 'light' | 'dark')"><option value="auto">{{ t('s_1e3rp8l') }}</option><option value="light">{{ t('s_4wwqgm') }}</option><option value="dark">{{ t('s_bsz4ru') }}</option></select></label></article><article class="card"><h2>{{ t('s_1apxo2s') }}</h2><p>{{ t('s_1apxo2s') }}{{ securityEnabled ? t('s_zjmqjk') : t('s_oxxuyg') }}</p><p v-if="security.error" class="error">{{ security.error.value?.message }}</p><button class="cta ghost" @click="router.push('/security')">{{ t('s_gpskv') }}</button></article></template></section></template>
